import{_ as n,o as i,c as t,ah as r}from"./chunks/framework.DDXs_i7t.js";const h=JSON.parse('{"title":"Update: Die COFAG-Milliarden und Benkos Schweigen","description":"Wir integrieren den COFAG-Skandal und René Benkos Auftritt im U-Ausschuss in das Projekt. Über 18,7 Millionen Gründe zum Schweigen.","frontmatter":{"title":"Update: Die COFAG-Milliarden und Benkos Schweigen","description":"Wir integrieren den COFAG-Skandal und René Benkos Auftritt im U-Ausschuss in das Projekt. Über 18,7 Millionen Gründe zum Schweigen.","date":"2026-02-28T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-28-cofag-integration.md","filePath":"logbuch/2026-02-28-cofag-integration.md"}'),a={name:"logbuch/2026-02-28-cofag-integration.md"};function s(o,e,d,l,u,g){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="update-die-cofag-milliarden-und-benkos-schweigen" tabindex="-1">Update: Die COFAG-Milliarden und Benkos Schweigen <a class="header-anchor" href="#update-die-cofag-milliarden-und-benkos-schweigen" aria-label="Permalink to &quot;Update: Die COFAG-Milliarden und Benkos Schweigen&quot;">​</a></h1><p>Heute haben wir die <strong>COFAG-Recherche</strong> in das Horten-Mysterium eingewebt. Es ist die perfekte moderne Fortsetzung: Was früher die „Arisierung“ war, ist heute die „Förderoptimierung“.</p><p><strong>Was wir gelernt haben:</strong></p><ul><li><strong>Der 18,7-Millionen-Punkt:</strong> Benko hat gezeigt, dass man nicht nur Geld <em>geben</em> kann (wie Heidi), sondern auch massiv Geld vom Staat <em>nehmen</em> kann, wenn man die richtigen Netzwerke hat.</li><li><strong>Die Kunst der Nichterinnerung:</strong> Benkos Auftritt vor dem U-Ausschuss im Mai 2024 ist ein Lehrstück in satirischer Realität. Ein „Beirat“, der sich an nichts erinnert, während Milliarden verschwinden.</li><li><strong>Das Luxus-Chalet:</strong> Dass 1,1 Millionen Euro Steuergeld in ein exklusives Chalet in Lech flossen, bietet uns fantastische visuelle Metaphern für <strong>Teil 4 des Drehbuchs</strong>.</li></ul><p>Wir haben Benko bereits eine neue Szene gewidmet, in der er erklärt, warum er eigentlich nur ein „gastgebender Beobachter“ seines eigenen Imperiums war.</p><p><em>Dokumentiert von Volti Sodala &amp; Gemini CLI. Februar 2026.</em></p>',6)])])}const m=n(a,[["render",s]]);export{h as __pageData,m as default};
